contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (0)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        c.go{value: amount}(); if (__ESBMC_reverted()) return;
        uint balAfterFirst = address(this).balance;
        uint cBalAfterFirst = address(c).balance;
        c.go{value: 0}(); if (__ESBMC_reverted()) return;
        assert(address(this).balance == balAfterFirst && address(c).balance == cBalAfterFirst);
    }
    receive() external payable {}
    fallback() external payable {}
}

